/* From Uiverse.io by Shoh2008 - Tags: card */
.__UIV_SCOPE__ .card {
  margin: 20px;
  padding: 20px;
  width: 300px;
  min-height: 200px;
  display: grid;
  grid-template-rows: 20px 50px 1fr 50px;
  border-radius: 10px;
  box-shadow: 0px 6px 10px rgba(0, 0, 0, 0.25);
  transition: all 0.2s;
}

.__UIV_SCOPE__ .card:hover {
  box-shadow: 0px 6px 10px rgba(0, 0, 0, 0.4);
  transform: scale(1.01);
}

.__UIV_SCOPE__ .card__link,
.__UIV_SCOPE__ .card__exit,
.__UIV_SCOPE__ .card__icon {
  position: relative;
  text-decoration: none;
  color: rgba(255, 255, 255, 0.9);
}

.__UIV_SCOPE__ .card__link::after {
  position: absolute;
  top: 25px;
  left: 0;
  content: "";
  width: 0%;
  height: 3px;
  background-color: rgba(255, 255, 255, 0.6);
  transition: all 0.5s;
}

.__UIV_SCOPE__ .card__link:hover::after {
  width: 100%;
}

.__UIV_SCOPE__ .text {
  color: white;
}

.__UIV_SCOPE__ .card__exit {
  grid-row: 1/2;
  justify-self: end;
}

.__UIV_SCOPE__ .card__icon {
  grid-row: 2/3;
  font-size: 30px;
}

.__UIV_SCOPE__ .card__title {
  grid-row: 3/4;
  font-weight: 400;
  color: #ffffff;
}

.__UIV_SCOPE__ .card__apply {
  grid-row: 4/5;
  align-self: center;
}

.__UIV_SCOPE__ .card-5 {
  background: radial-gradient(#f588d8, #c0a3e5);
}

@media (max-width: 1600px) {
  .__UIV_SCOPE__ .cards {
    justify-content: center;
  }
}
